  useMotionValueEvent(scrollYProgress, "change", (latest) => {
    const progress = clamp(latest, 0, 1);
    const nextActiveIndex = clamp(Math.floor(progress * items.length), 0, items.length - 1);
    const nextCompletedCount = clamp(Math.floor(progress * items.length), 0, items.length);

    setActiveIndex(nextActiveIndex);
    setCompletedCount(nextCompletedCount);
  });

  return (
    <section id="experience" ref={sectionRef} className="px-6 py-20 sm:px-10">
      <div className="mx-auto w-full max-w-6xl">
        <h2 className="text-sm uppercase tracking-[0.18em] text-[var(--accent)]">Experience</h2>
        {prefersReducedMotion ? (
          <StaticExperience items={items} />
        ) : (
          <div className="mt-8 grid gap-8 lg:grid-cols-[minmax(0,1fr)_minmax(18rem,24rem)] lg:items-start">
            <ol className="order-2 space-y-4 lg:order-1">
              {experience.map((entry, index) => (
                <li key={`${entry.company}-${entry.start}`}>
                  <ExperienceDetails
                    entry={entry}
                    isActive={index === activeIndex}
                    prefersReducedMotion={Boolean(prefersReducedMotion)}
                  />
                </li>
              ))}
            </ol>
            <div className="order-1 lg:sticky lg:top-20 lg:order-2">
              <TimelineSummary items={items} activeIndex={activeIndex} completedCount={completedCount} />
            </div>
          </div>
        )}
      </div>
    </section>
  );
}

