{"cmd":"npx --yes -p playwright@latest node <<'JS'
const { chromium } = require('playwright');

const companies = [
  'SIMIT',
  'Roularta Media Group',
  'Zora Robotics',
  'NineID',
  'Noordzee Helikopters Vlaanderen',
  'Easypost',
];

async function checkDesktop(browser) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 1000 } });
  await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
  await page.locator('#experience').scrollIntoViewIfNeeded();
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/experience-desktop-start.png', fullPage: false });

  const start = await page.evaluate((companies) => {
    const section = document.querySelector('#experience');
    const text = section?.textContent || '';
    return {
      hasTimeline: text.includes('Timeline'),
      companiesPresent: companies.every((company) => text.includes(company)),
      detailedLists: section?.querySelectorAll('article ul').length || 0,
      summaryArticles: section?.querySelectorAll('article').length || 0,
    };
  }, companies);

  await page.evaluate(() => {
    const section = document.querySelector('#experience');
    if (!section) return;
    const rect = section.getBoundingClientRect();
    const absoluteTop = rect.top + window.scrollY;
    window.scrollTo({ top: absoluteTop + section.scrollHeight - window.innerHeight * 0.7, behavior: 'instant' });
  });
  await page.waitForTimeout(900);
  await page.screenshot({ path: '/tmp/experience-desktop-end.png', fullPage: false });

  const end = await page.evaluate((companies) => {
    const section = document.querySelector('#experience');
    const text = section?.textContent || '';
    const contact = document.querySelector('#contact');
    const timeline = section?.querySelector('.lg\\:sticky');
    const timelineRect = timeline?.getBoundingClientRect();
    const contactRect = contact?.getBoundingClientRect();
    return {
      companiesPresent: companies.every((company) => text.includes(company)),
      hasFinalCount: text.includes('6 / 6'),
      timelineBeforeContact: Boolean(timelineRect && contactRect && timelineRect.bottom <= contactRect.top),
    };
  }, companies);

  await page.close();
  return { start, end };
}

async function checkMobile(browser) {
  const page = await browser.newPage({ viewport: { width: 390, height: 900 } });
  await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
  await page.locator('#experience').scrollIntoViewIfNeeded();
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/experience-mobile.png', fullPage: false });

  const result = await page.evaluate((companies) => {
    const section = document.querySelector('#experience');
    const text = section?.textContent || '';
    const stacked = Array.from(section?.querySelectorAll('ol') || []).some((ol) => {
      const style = window.getComputedStyle(ol);
      return style.display !== 'none' && ol.textContent?.includes('Timeline') === false && companies.every((company) => section?.textContent?.includes(company));
    });
    return {
      companiesPresent: companies.every((company) => text.includes(company)),
      hasTimeline: text.includes('Timeline'),
      viewportWidth: window.innerWidth,
      hasVisibleStackedList: stacked,
      horizontalOverflow: document.documentElement.scrollWidth > window.innerWidth + 1,
    };
  }, companies);

  await page.close();
  return result;
}

async function checkReducedMotion(browser) {
  const context = await browser.newContext({ viewport: { width: 1280, height: 900 }, reducedMotion: 'reduce' });
  const page = await context.newPage();
  await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
  await page.locator('#experience').scrollIntoViewIfNeeded();
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/experience-reduced-motion.png', fullPage: false });

  const result = await page.evaluate((companies) => {
    const section = document.querySelector('#experience');
    const text = section?.textContent || '';
    return {
      companiesPresent: companies.every((company) => text.includes(company)),
      hasTimeline: text.includes('Timeline'),
      detailedLists: section?.querySelectorAll('article ul').length || 0,
      articleCount: section?.querySelectorAll('article').length || 0,
    };
  }, companies);

  await context.close();
