    const results = {
      desktop: await checkDesktop(browser),
      mobile: await checkMobile(browser),
      reducedMotion: await checkReducedMotion(browser),
    };
    console.log(JSON.stringify(results, null, 2));
  } finally {
    await browser.close();
  }
})();
