const { test, expect } = require('@playwright/test');

const companies = [
  'SIMIT',
  'Roularta Media Group',
  'Zora Robotics',
  'NineID',
  'Noordzee Helikopters Vlaanderen',
  'Easypost',
];

test('desktop timeline renders and completes without overlapping contact', async ({ page }) => {
  await page.setViewportSize({ width: 1440, height: 1000 });
  await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
  await page.locator('#experience').scrollIntoViewIfNeeded();
  await expect(page.locator('#experience')).toContainText('Timeline');
  for (const company of companies) await expect(page.locator('#experience')).toContainText(company);

  await page.evaluate(() => {
    const section = document.querySelector('#experience');
    const rect = section.getBoundingClientRect();
    window.scrollTo(0, rect.top + window.scrollY + section.scrollHeight - window.innerHeight * 0.55);
  });
  await page.waitForTimeout(700);
  await page.screenshot({ path: '/tmp/experience-desktop-scrolled.png' });
  await expect(page.locator('#experience')).toContainText('6 / 6');

  const noOverlap = await page.evaluate(() => {
    const timeline = document.querySelector('#experience .lg\\:sticky');
    const contact = document.querySelector('#contact');
    if (!timeline || !contact) return false;
    return timeline.getBoundingClientRect().bottom <= contact.getBoundingClientRect().top;
  });
  expect(noOverlap).toBe(true);
});

test('mobile timeline is stacked and does not horizontally overflow', async ({ page }) => {
  await page.setViewportSize({ width: 390, height: 900 });
  await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
  await page.locator('#experience').scrollIntoViewIfNeeded();
  await page.screenshot({ path: '/tmp/experience-mobile-check.png' });
  for (const company of companies) await expect(page.locator('#experience')).toContainText(company);
  const horizontalOverflow = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth + 1);
  expect(horizontalOverflow).toBe(false);
});

test('reduced motion shows static timeline and readable entries', async ({ browser }) => {
  const context = await browser.newContext({ reducedMotion: 'reduce', viewport: { width: 1280, height: 900 } });
  const page = await context.newPage();
  await page.goto('http://localhost:3000', { waitUntil: 'networkidle' });
  await page.locator('#experience').scrollIntoViewIfNeeded();
  await page.screenshot({ path: '/tmp/experience-reduced-motion-check.png' });
  for (const company of companies) await expect(page.locator('#experience')).toContainText(company);
  await expect(page.locator('#experience')).toContainText('6 / 6');
  const detailedLists = await page.locator('#experience article ul').count();
  expect(detailedLists).toBe(6);
  await context.close();
});
